import {test,expect} from '@playwright/test';
import {writeFileSync} from 'node:fs';
import {installProbes} from '../__tests__/browser/fixtures/probes';
import type {} from '../__tests__/browser/fixtures/glyph-atlas';
test('count actual SDF instance updates',async({browser})=>{
 const results=[];
 for(const backend of ['core','ecs']){
  const page=await browser.newPage();await page.addInitScript(installProbes);
  await page.goto(`/glyph-atlas.html?backend=${backend}`);await expect(page.locator('output')).toHaveText('Ready');
  await page.evaluate(()=>window.mixedRenderer.textBatching(true));
  await page.evaluate(()=>window.mixedRenderer.configure(1000,'grouped',false));
  const result=await page.evaluate(async backend=>{
   const {SDF}=await import(`/@fs/workspace/scratch/4ac374cddc05/sdf-row-updates/packages/${backend}/src/drawcalls/SDF.ts`);
   const stats={geometryBuilds:0,packedRows:0,attributeBytes:0,matrixBytes:0,attributeWrites:0,matrixWrites:0};
   const p=SDF.prototype,geometry=p.createGeometry,pack=p.generateBuffer,render=p.render;
   p.createGeometry=function(...args:any[]){if(this.instanced)stats.geometryBuilds++;return geometry.apply(this,args);};
   p.generateBuffer=function(...args:any[]){if(this.instanced)stats.packedRows++;return pack.apply(this,args);};
   p.render=function(...args:any[]){if(!this.instanced)return render.apply(this,args);
    const restorers=[];
    for(const slot of [1,2]) {const buffer=this.vertexBuffers[slot],set=buffer.setSubData;
     buffer.setSubData=function(...input:any[]){if(slot===1){stats.attributeBytes+=input[1].byteLength;stats.attributeWrites++;}else{stats.matrixBytes+=input[1].byteLength;stats.matrixWrites++;}return set.apply(this,input);};
     restorers.push(()=>buffer.setSubData=set);
    }
    try{return render.apply(this,args);}finally{restorers.reverse().forEach(f=>f());}
   };
   try {const frame=await window.mixedRenderer.measure('edit',2,1);return {backend,frames:3,...stats,visible:frame.visible,native:frame.native};}
   finally{p.createGeometry=geometry;p.generateBuffer=pack;p.render=render;}
  },backend);
  results.push(result);console.log(result);await page.evaluate(()=>window.mixedRenderer.destroy());await page.close();
 }
 writeFileSync(process.env.SDF_ROWS_PROBE_OUTPUT??'.test-results/rows-before.json',JSON.stringify(results,null,2)+'\n');
});
